using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class AEAudit {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/Review/2026-11-12_1F_Abandoned/";
 static float[] A(Vector3 a)=>new[]{a.x,a.y,a.z};
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F edit required");var root=GameObject.Find("1F_AbandonedFactory");var errors=new List<string>();var p=JObject.Parse(File.ReadAllText(R+"/SourceAssets/F1_AbandonedCamouflage/before_layout.json"));
  foreach(var f in root.GetComponentsInChildren<MeshFilter>())if(!f.sharedMesh)errors.Add("Missing mesh "+f.name);foreach(var rr in root.GetComponentsInChildren<Renderer>())if(rr.sharedMaterials.Any(m=>!m||!m.shader||m.shader.name.Contains("Error")))errors.Add("Missing material "+rr.name);
  var arrivals=new List<object>();foreach(var a in p["arrivals"]){var v=a["position"];var expected=new Vector3((float)v[0],(float)v[1],(float)v[2]);var g=GameObject.Find("Arrival_FromB1_"+(string)a["id"]);bool match=g&&Vector3.Distance(g.transform.position,expected)<.001f;if(!match)errors.Add("Arrival drift "+a["id"]);arrivals.Add(new{id=(string)a["id"],match,position=g?A(g.transform.position):null});}
  var terrain=root.GetComponentInChildren<Terrain>();if(!terrain||!terrain.GetComponent<TerrainCollider>())errors.Add("Missing Terrain/Collider");var td=terrain.terrainData;var h=td.GetHeights(0,0,td.heightmapResolution,td.heightmapResolution);float min=1,max=0;foreach(float value in h){min=Mathf.Min(min,value);max=Mathf.Max(max,value);}var holes=td.GetHoles(0,0,td.holesResolution,td.holesResolution);int holeCount=0;foreach(bool v in holes)if(!v)holeCount++;var rays=new List<object>();Physics.SyncTransforms();foreach(var r in p["rooms"]){var pos=new Vector3((float)r["x"],.3f,(float)r["z"]);bool hit=Physics.Raycast(pos,Vector3.down,out var rh,.6f);if(!hit)errors.Add("No floor "+r["id"]);rays.Add(new{id=(string)r["id"],hit,normal=hit?A(rh.normal):null,collider=hit?rh.collider.name:null});}
  foreach(var n in new[]{"ExteriorGround","F1_Yard","F1_GroundFloor","F1_OperationalSigns","F1_Wayfinding"})if(GameObject.Find(n))errors.Add("Old operating surface active "+n);
  var lights=root.GetComponentsInChildren<Light>().Where(l=>l.enabled).ToArray();var emissions=root.GetComponentsInChildren<Renderer>().SelectMany(rr=>rr.sharedMaterials).Where(m=>m&&m.IsKeywordEnabled("_EMISSION")&&m.HasProperty("_EmissionColor")&&m.GetColor("_EmissionColor").maxColorComponent>.001f).Distinct().Select(m=>m.name).ToArray();if(emissions.Length>0)errors.Add("Powered emission "+string.Join(",",emissions));
  var result=new{scene=s.path,saved=!s.isDirty,errors,arrivals,floorRays=rays,terrain=new{size=A(td.size),position=A(terrain.transform.position),resolution=td.heightmapResolution,layers=td.terrainLayers.Length,minWorldY=min*td.size.y+terrain.transform.position.y,maxWorldY=max*td.size.y+terrain.transform.position.y,holes=holeCount,collider=terrain.GetComponent<TerrainCollider>()!=null,shader=terrain.materialTemplate.shader.name},activeLights=lights.Length,shadowLights=lights.Count(l=>l.shadows!=LightShadows.None),poweredEmissions=emissions,activeRenderers=root.GetComponentsInChildren<Renderer>().Length,lodGroups=root.GetComponentsInChildren<LODGroup>().Length,missingScripts=root.GetComponentsInChildren<Transform>(true).Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)),readableMeshes=root.GetComponentsInChildren<MeshFilter>().Count(f=>f.sharedMesh&&AssetDatabase.GetAssetPath(f.sharedMesh).Contains("/AE_")&&f.sharedMesh.isReadable)};
  File.WriteAllText(O+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
}
